
from arpeggio_constants import CONTACT_FIELDS
import pandas as pd

def parse_contacts(file_path: str, split_atom_col: True) -> pd.DataFrame:
    """ Parses the .contacts file generated by Arpeggio and returns a dataframe.

    NOTE:
    The atoms in the .contacts file are represented as:
        `chain/res_num/atom`
    This function splits these into three separate columns.

    Args:
        file_path (str): Path to the .contacts file.

    Returns:
        pd.DataFrame: DataFrame containing the parsed contact information.
    """

    with open(file_path, 'r') as f:
        lines = f.readlines()

    df = pd.DataFrame(columns=CONTACT_FIELDS)
    for line in lines:
        parts = line.split()
        row_to_add = {k: v for k, v in zip(CONTACT_FIELDS, parts)}
        df = pd.concat([df, pd.DataFrame([row_to_add])], ignore_index=True)

    if not split_atom_col:
        return df

    df[["chain_1", "res_num_1", "atom_1"]] = df["atom_1"].str.split("/", expand=True)
    df[["chain_2", "res_num_2", "atom_2"]] = df["atom_2"].str.split("/", expand=True)

    front_cols = [
        "chain_1", "res_num_1", "atom_1",
        "chain_2", "res_num_2", "atom_2"
    ]
    df = df[front_cols + [col for col in df.columns if col not in front_cols]]

    return df

